CREATE TABLE trip_groups(carrier_id text REFERENCES carriers(id),id uuid,planning_run_id uuid,driver_id text,version integer NOT NULL DEFAULT 1,status text NOT NULL CHECK(status IN ('offered','accepted','rejected','completed')),body jsonb NOT NULL,PRIMARY KEY(carrier_id,id),FOREIGN KEY(carrier_id,planning_run_id) REFERENCES planning_runs(carrier_id,id),FOREIGN KEY(carrier_id,driver_id) REFERENCES resources(carrier_id,id));
CREATE TABLE trip_members(carrier_id text,group_id uuid,assignment_id uuid,PRIMARY KEY(carrier_id,assignment_id),FOREIGN KEY(carrier_id,group_id) REFERENCES trip_groups(carrier_id,id),FOREIGN KEY(carrier_id,assignment_id) REFERENCES assignments(carrier_id,id));
CREATE TABLE plan_approvals(carrier_id text,id uuid,planning_run_id uuid,approved_by text NOT NULL,evidence jsonb NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(carrier_id,id),FOREIGN KEY(carrier_id,planning_run_id) REFERENCES planning_runs(carrier_id,id));
CREATE TABLE manifests(carrier_id text,assignment_id uuid,body jsonb NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(carrier_id,assignment_id),FOREIGN KEY(carrier_id,assignment_id) REFERENCES assignments(carrier_id,id));
